## `config.ts`

Typed view over stack config so `dev.yaml` / `prod.yaml` are the *only* place environment differences live.

```ts
import * as pulumi from "@pulumi/pulumi";

export interface EnvSpec {
    env: "dev" | "prod";
    region: string;

    db: {
        instanceClass: string;
        allocatedStorage: number;
        multiAz: boolean;
        storageEncrypted: boolean;
        backupRetentionDays: number;
    };

    bucket: {
        replicaRegion?: string;      // prod only
    };

    /** OIDC provider ARN of the EKS cluster (IRSA trust). */
    oidcProviderArn: pulumi.Input<string>;
    oidcProviderUrl: pulumi.Input<string>;
    serviceAccountNamespace: string;
    serviceAccountName: string;
}

export function loadEnvSpec(): EnvSpec {
    const cfg = new pulumi.Config();
    const stack = pulumi.getStack();

    if (stack !== "dev" && stack !== "prod") {
        throw new Error(`unsupported stack '${stack}'; expected dev|prod`);
    }

    return {
        env: stack,
        region: new pulumi.Config("aws").require("region"),
        db: cfg.requireObject<EnvSpec["db"]>("db"),
        bucket: cfg.getObject<EnvSpec["bucket"]>("bucket") ?? {},
        oidcProviderArn: cfg.require("oidcProviderArn"),
        oidcProviderUrl: cfg.require("oidcProviderUrl"),
        serviceAccountNamespace: cfg.get("serviceAccountNamespace") ?? "default",
        serviceAccountName: cfg.get("serviceAccountName") ?? "web-app",
    };
}
```

