## `components/appPlatform.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as random from "@pulumi/random";
import { EnvSpec } from "../config";

export interface AppPlatformArgs {
    spec: EnvSpec;
    /** VPC + subnets the RDS instance lives in (private). */
    vpcId: pulumi.Input<string>;
    privateSubnetIds: pulumi.Input<string>[];
    /** SGs allowed to reach Postgres (e.g. the EKS node SG). */
    clientSecurityGroupIds: pulumi.Input<string>[];
    dbName?: string;
    tags?: Record<string, string>;
}

export class AppPlatform extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly bucketArn: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly dbPort: pulumi.Output<number>;
    /** Marked secret; never surfaces in plaintext state diffs or `pulumi stack output`. */
    public readonly dbConnectionString: pulumi.Output<string>;
    public readonly connectionSecretArn: pulumi.Output<string>;
    public readonly serviceRoleArn: pulumi.Output<string>;

    constructor(name: string, args: AppPlatformArgs, opts?: pulumi.ComponentResourceOptions) {
        super("acme:app:AppPlatform", name, {}, opts);
        const parent = { parent: this };

        const spec = args.spec;
        const isProd = spec.env === "prod";
        const dbName = args.dbName ?? "appdb";
        const tags = { Environment: spec.env, ManagedBy: "pulumi", Component: name, ...(args.tags ?? {}) };

        // ------------------------------------------------------------------
        // 1. S3 bucket — versioned, encrypted, fully private
        // ------------------------------------------------------------------
        const bucket = new aws.s3.BucketV2(`${name}-assets`, {
            forceDestroy: !isProd,
            tags,
        }, parent);

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: bucket.id,
            versioningConfiguration: { status: "Enabled" },
        }, parent);

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-sse`, {
            bucket: bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
                bucketKeyEnabled: true,
            }],
        }, parent);

        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, parent);

        new aws.s3.BucketPolicy(`${name}-assets-tls-only`, {
            bucket: bucket.id,
            policy: bucket.arn.apply(arn => JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Sid: "DenyInsecureTransport",
                    Effect: "Deny",
                    Principal: "*",
                    Action: "s3:*",
                    Resource: [arn, `${arn}/*`],
                    Condition: { Bool: { "aws:SecureTransport": "false" } },
                }],
            })),
        }, parent);

        // --- prod only: cross-region replication to us-west-2 -------------
        if (isProd && spec.bucket.replicaRegion) {
            const replicaProvider = new aws.Provider(`${name}-replica-provider`, {
                region: spec.bucket.replicaRegion as aws.Region,
            }, parent);

            const replica = new aws.s3.BucketV2(`${name}-assets-replica`, { tags },
                { parent: this, provider: replicaProvider });

            new aws.s3.BucketVersioningV2(`${name}-assets-replica-versioning`, {
                bucket: replica.id,
                versioningConfiguration: { status: "Enabled" },
            }, { parent: this, provider: replicaProvider });

            new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-replica-sse`, {
                bucket: replica.id,
                rules: [{ applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" } }],
            }, { parent: this, provider: replicaProvider });

            new aws.s3.BucketPublicAccessBlock(`${name}-assets-replica-pab`, {
                bucket: replica.id,
                blockPublicAcls: true, blockPublicPolicy: true,
                ignorePublicAcls: true, restrictPublicBuckets: true,
            }, { parent: this, provider: replicaProvider });

            const replRole = new aws.iam.Role(`${name}-replication`, {
                assumeRolePolicy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{ Effect: "Allow", Principal: { Service: "s3.amazonaws.com" }, Action: "sts:AssumeRole" }],
                }),
                tags,
            }, parent);

            new aws.iam.RolePolicy(`${name}-replication-policy`, {
                role: replRole.id,
                policy: pulumi.all([bucket.arn, replica.arn]).apply(([src, dst]) => JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        { Effect: "Allow", Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"], Resource: src },
                        { Effect: "Allow", Action: ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"], Resource: `${src}/*` },
                        { Effect: "Allow", Action: ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"], Resource: `${dst}/*` },
                    ],
                })),
            }, parent);

            new aws.s3.BucketReplicationConfig(`${name}-assets-replication`, {
                role: replRole.arn,
                bucket: bucket.id,
                rules: [{
                    id: "replicate-all",
                    status: "Enabled",
                    filter: {},
                    deleteMarkerReplication: { status: "Enabled" },
                    destination: { bucket: replica.arn, storageClass: "STANDARD_IA" },
                }],
            }, parent);
        }

        // ------------------------------------------------------------------
        // 2. RDS PostgreSQL — private, deletion-protected, backed up
        // ------------------------------------------------------------------
        const dbPassword = new random.RandomPassword(`${name}-db-password`, {
            length: 32,
            special: true,
            overrideSpecial: "!#$%&*()-_=+[]{}<>:?",
        }, parent);

        const subnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: args.privateSubnetIds,
            tags,
        }, parent);

        const dbSg = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            vpcId: args.vpcId,
            description: `Postgres access for ${name}`,
            egress: [{ protocol: "-1", fromPort: 0, toPort: 0, cidrBlocks: ["0.0.0.0/0"] }],
            tags,
        }, parent);

        args.clientSecurityGroupIds.forEach((sg, i) =>
            new aws.ec2.SecurityGroupRule(`${name}-db-ingress-${i}`, {
                type: "ingress",
                securityGroupId: dbSg.id,
                sourceSecurityGroupId: sg,
                protocol: "tcp",
                fromPort: 5432,
                toPort: 5432,
            }, parent));

        const db = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "16.3",
            instanceClass: spec.db.instanceClass,
            allocatedStorage: spec.db.allocatedStorage,
            storageType: "gp3",

            dbName,
            username: "appuser",
            password: dbPassword.result,

            dbSubnetGroupName: subnetGroup.name,
            vpcSecurityGroupIds: [dbSg.id],
            publiclyAccessible: false,              // AC #2

            multiAz: spec.db.multiAz,
            storageEncrypted: spec.db.storageEncrypted,

            backupRetentionPeriod: spec.db.backupRetentionDays,  // >= 7, enforced below
            backupWindow: "03:00-04:00",
            maintenanceWindow: "sun:04:30-sun:05:30",
            copyTagsToSnapshot: true,

            deletionProtection: true,                // AC #2, both envs
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-${spec.env}-final`,
            applyImmediately: !isProd,

            performanceInsightsEnabled: isProd,
            enabledCloudwatchLogsExports: ["postgresql", "upgrade"],
            tags,
        }, { ...parent, protect: isProd });

        if (spec.db.backupRetentionDays < 7) {
            throw new Error("backupRetentionDays must be >= 7");
        }

        // Connection string: secret in Pulumi state (encrypted by the stack's
        // secrets provider) AND materialised into Secrets Manager for the app.
        const connString = pulumi.secret(
            pulumi.interpolate`postgresql://appuser:${dbPassword.result}@${db.address}:${db.port}/${dbName}?sslmode=require`
        );

        const secret = new aws.secretsmanager.Secret(`${name}-db-conn`, {
            name: `${spec.env}/${name}/db-connection`,
            description: "Postgres connection string",
            recoveryWindowInDays: isProd ? 30 : 0,
            tags,
        }, parent);

        new aws.secretsmanager.SecretVersion(`${name}-db-conn-v`, {
            secretId: secret.id,
            secretString: connString,
        }, parent);

        // ------------------------------------------------------------------
        // 3. IAM role for the service account (IRSA, least privilege)
        // ------------------------------------------------------------------
        const assumeRolePolicy = pulumi
            .all([spec.oidcProviderArn, spec.oidcProviderUrl])
            .apply(([arn, url]) => {
                const host = url.replace(/^https:\/\//, "");
                return JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Federated: arn },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: {
                                [`${host}:aud`]: "sts.amazonaws.com",
                                [`${host}:sub`]:
                                    `system:serviceaccount:${spec.serviceAccountNamespace}:${spec.serviceAccountName}`,
                            },
                        },
                    }],
                });
            });

        const role = new aws.iam.Role(`${name}-sa`, {
            assumeRolePolicy,
            description: `IRSA role for ${spec.serviceAccountNamespace}/${spec.serviceAccountName}`,
            maxSessionDuration: 3600,
            tags,
        }, parent);

        // Explicit actions only — no wildcards, resources scoped to this stack.
        new aws.iam.RolePolicy(`${name}-sa-policy`, {
            role: role.id,
            policy: pulumi.all([bucket.arn, secret.arn]).apply(([bucketArn, secretArn]) => JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Sid: "AssetsList",
                        Effect: "Allow",
                        Action: ["s3:ListBucket", "s3:GetBucketLocation"],
                        Resource: bucketArn,
                    },
                    {
                        Sid: "AssetsObjects",
                        Effect: "Allow",
                        Action: ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:GetObjectVersion"],
                        Resource: `${bucketArn}/*`,
                    },
                    {
                        Sid: "ReadDbConnectionSecret",
                        Effect: "Allow",
                        Action: ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"],
                        Resource: secretArn,
                    },
                ],
            })),
        }, parent);

        this.bucketName = bucket.bucket;
        this.bucketArn = bucket.arn;
        this.dbEndpoint = db.address;
        this.dbPort = db.port;
        this.dbConnectionString = connString;
        this.connectionSecretArn = secret.arn;
        this.serviceRoleArn = role.arn;

        this.registerOutputs({
            bucketName: this.bucketName,
            dbEndpoint: this.dbEndpoint,
            serviceRoleArn: this.serviceRoleArn,
            connectionSecretArn: this.connectionSecretArn,
        });
    }
}
