## `index.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { loadEnvSpec } from "./config";
import { AppPlatform } from "./components/appPlatform";

const spec = loadEnvSpec();
const cfg = new pulumi.Config();

const platform = new AppPlatform(`web-${spec.env}`, {
    spec,
    vpcId: cfg.require("vpcId"),
    privateSubnetIds: cfg.requireObject<string[]>("privateSubnetIds"),
    clientSecurityGroupIds: cfg.requireObject<string[]>("nodeSecurityGroupIds"),
    dbName: "appdb",
    tags: { Project: "web-app", Owner: "platform-team" },
});

export const bucketName = platform.bucketName;
export const dbEndpoint = platform.dbEndpoint;
export const serviceRoleArn = platform.serviceRoleArn;
export const connectionSecretArn = platform.connectionSecretArn;
// Output stays encrypted at rest; requires `--show-secrets` to reveal.
export const dbConnectionString = platform.dbConnectionString;
```

